from research_helpers import *
L=ev('https://www.lna-sante.com/','Official issuer describes care facilities, rehabilitation, home hospitalization and clinical services; no named own in-scope products found.')
R=ev('https://www.lna-sante.com/capr/etudes/','Reviewed issuer research portfolio: named observational/interventional studies and use of third-party Omnipod5/Skelex/MUSICCARE equipment do not establish ownership/development of those products.')
W=ev('https://www.worldwidewh.com/','Issuer identifies itself as listed diversified healthcare investment company; portfolio-company shares do not establish direct rights in their medicines.')
B=ev('https://www.sec.gov/Archives/edgar/data/720002/000110465916124080/a16-12421_1ex99d1.htm','Primary issuer release confirms Cheviot Financial merger into MainSource completedMay20 2016; financial business identity inconsistent with supplied website.')
C=ev('https://www.sec.gov/Archives/edgar/data/1459188/000121390026033022/ea0281753-10k_charging.htm','Charging Robotics has different issuer CIK1459188 and2023 acquisition history; not evidence it is the same legal entity as Cheviot Financial CIK1528843. Ticker reuse does not establish corporate continuity.')
S=ev('https://www.smoltek.com/smoltek-semi/capacitors/','Official page describes CNF-MIM capacitor technology for semiconductor packaging.')
G=ev('https://www.smoltek.com/glossary/','Issuer defines SmolGrow trademarked patterned-carbon-nanofiber growth technology.')
P=ev('https://www.smoltek.com/wp-content/uploads/2025/06/smoltek-semi-strategic-update-2025-final.pdf','Issuer roadmap explicitly names Gen-Zero/One/Two/Three. GenTwo/Three target dates/specifications are roadmap intentions, not confirmed production.')
U=ev('https://www.smoltek.com/wp-content/uploads/2026/02/snh-q4-2025-en.pdf','February2026 report confirms Gen-One prototype/low-volume capability and ongoing validation; not assumed mass-market commercial availability.')
H=ev('https://www.smoltek.com/smoltek-hydrogen/','Separate PTE/ECM electrode technology concerns hydrogen production and fuel-cell catalysis; no hydrogen-storage product demonstrated, so excluded under generation-only exclusion in shared sector taxonomy.')
ps=[p('CNF-MIM','Carbon-nanofiber metal-insulator-metal capacitor technology.',S,typ='technology',sector='semiconductors',sub='materials_and_packaging'),p('SmolGrow','Patterned-carbon-nanofiber growth technology.',G,typ='technology',sector='semiconductors',sub='materials_and_packaging')]
for name,life in [('Gen-Zero','unknown'),('Gen-One','development'),('Gen-Two','research'),('Gen-Three','research')]:ps.append(p('Smoltek '+name,'Named CNF-MIM capacitor development generation.',P,life,sector='semiconductors',sub='materials_and_packaging',attributes={'generation':name,'roadmap_only':name in ['Gen-Two','Gen-Three']},evidence=[P,U] if name=='Gen-One' else [P]))
companies=[company('LNA Sante SA',[],[L,R],'Public care-service and clinical-research portfolios reviewed. No own named therapeutics, diagnostics, research tools, robotics, semiconductors or storage products identified. Clinical study names, facilities and use of third-party equipment do not create product-ownership records.',status='complete'),company('WORLDWIDE HEALTH.TR LS-25',[],[W],'Listed investment trust with diversified healthcare-company securities portfolio; no direct named in-scope product rights identified. Minority holdings not treated as medicine development/ownership.',status='complete'),company('Cheviot Financial Corp',[],[B,C],'ENTITY MISMATCH: canonical bank name and supplied Charging Robotics website refer to different issuers. No Charging Robotics products attributed to Cheviot. Resolve company identity upstream before product attribution.'),company('Smoltek Nanotech Holding AB',ps,[S,G,P,U,H],'Named semiconductor platform and four development generations reviewed. Future roadmap specs not treated as achieved. Hydrogen-production PTE/ECM technology excluded from storage-only taxonomy absent storage application evidence. Follow-up later2026 generation progress and legacy branded semiconductor platforms.')]
(out/'batch-0033.json').write_text(json.dumps({'companies':companies},indent=2));print(len(ps))
